{#- Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/feature-rows.json
    The features as rows: text beside a picture (the rows layout of FeatureGrid). Icons are Lucide names.
    Props (p): features, mediaSide. -#}
{%- set v_features = (p.features ?? null) -%}
{%- set v_mediaSide = (p.mediaSide ?? 'end') -%}
{%- set c_6 -%}
  {%- for v_feature in og_l(v_features) %}
    {%- set c_5 -%}
      {%- set c_3 -%}
        {{ include('icons/LucideIcon.html.twig', {'name': og_s(og_get(v_feature, ['icon'])), 'size': 24}, with_context = false) }}
        {%- set c_1 -%}
          {{ og_text(og_get(v_feature, ['title'])) }}
        {%- endset -%}
        {{ include('compose/Title.html.twig', {'as': 3, 'size': 'xl', 'weight': 'bold', 'children': c_1}, with_context = false) }}
        {%- set c_2 -%}
          {{ og_text(og_get(v_feature, ['text'])) }}
        {%- endset -%}
        {{ include('compose/Text.html.twig', {'size': 'base', 'class': 'text-muted-foreground', 'children': c_2}, with_context = false) }}
      {%- endset -%}
      {{ include('compose/Stack.html.twig', {'gap': '2', 'class': 'min-w-0', 'children': c_3}, with_context = false) }}
      {%- set c_4 -%}
        {{ include('blocks/media-frame.html.twig', {'p': {'alt': og_get(v_feature, ['title']), 'ratio': '4/3'}}, with_context = false) }}
      {%- endset -%}
      {{ include('compose/Box.html.twig', {'class': og_s(og_cnv(['w-full min-w-0', (og_t(og_eq(v_mediaSide, 'start')) ? 'md:order-first' : (og_t(og_eq(v_mediaSide, 'alternate')) ? 'md:group-even:order-first' : ''))])), 'children': c_4}, with_context = false) }}
    {%- endset -%}
    {{ include('compose/Grid.html.twig', {'cols': '1-2', 'class': 'group items-center gap-8', 'attrs': og_attrs(['data-slot', 'feature-card']), 'children': c_5}, with_context = false) }}
  {%- endfor %}
{%- endset -%}
{{ include('compose/Stack.html.twig', {'gap': '8', 'align': 'stretch', 'attrs': og_attrs(['data-slot', 'feature-rows']), 'children': c_6}, with_context = false) }}
